import type { MenuSteps } from "./menuStepsTypes";

export const ENERGY_HOUSE_STEPS: MenuSteps = {
  inverters: [
    { target: "inv-head", placement: "bottom",
      t: ["The totals and the solar node", "Los totales y el nodo solar", "Die Summen und der Solarknoten", "Les totaux et le nœud solaire", "I totali e il nodo solare", "合計とソーラーノード", "汇总与太阳能节点", "Os totais e o nó solar"],
      b: ["The tiles add up the power of the panels, the load, the battery and the grid across your inverters. The readings come from a solar node (ARMOR-SOLAR, an ESP32-S3 beside the equipment) that talks to the inverters and batteries through its serial ports and sends what it reads; Studio only shows it, so the readings are read-only. The equipment is declared below with \"Add an inverter\": a name, the node that reads it, its identifier in the node's settings, its model and how it is connected.",
        "Las fichas suman la potencia de los paneles, la carga, la batería y la red entre tus inversores. Las lecturas vienen de un nodo solar (ARMOR-SOLAR, un ESP32-S3 junto al equipo) que habla con inversores y baterías por sus puertos serie y envía lo que lee; Studio solo lo muestra, así que las lecturas son de solo lectura. El equipo se declara abajo con \"Añadir un inversor\": un nombre, el nodo que lo lee, su identificador en los ajustes del nodo, su modelo y cómo está conectado.",
        "Die Kacheln addieren Leistung der Module, Last, Batterie und Netz über Ihre Wechselrichter. Die Werte kommen von einem Solarknoten (ARMOR-SOLAR, ein ESP32-S3 am Gerät), der über seine seriellen Ports mit Wechselrichtern und Batterien spricht und das Gelesene sendet; Studio zeigt es nur an, die Werte sind schreibgeschützt. Das Gerät melden Sie unten mit \"Wechselrichter hinzufügen\" an: Name, lesender Knoten, Kennung in den Knoteneinstellungen, Modell und Anschlussart.",
        "Les tuiles additionnent la puissance des panneaux, la charge, la batterie et le réseau sur vos onduleurs. Les mesures viennent d'un nœud solaire (ARMOR-SOLAR, un ESP32-S3 près de l'équipement) qui parle aux onduleurs et batteries par ses ports série et envoie ce qu'il lit ; Studio ne fait que l'afficher, les mesures sont en lecture seule. L'équipement se déclare plus bas avec « Ajouter un onduleur » : un nom, le nœud qui le lit, son identifiant dans les réglages du nœud, son modèle et sa connexion.",
        "Le schede sommano potenza dei pannelli, carico, batteria e rete tra i tuoi inverter. Le letture vengono da un nodo solare (ARMOR-SOLAR, un ESP32-S3 accanto all'apparecchio) che parla con inverter e batterie dalle sue porte seriali e invia ciò che legge; Studio lo mostra soltanto, quindi le letture sono di sola lettura. L'apparecchio si dichiara sotto con \"Aggiungi un inverter\": un nome, il nodo che lo legge, il suo identificativo nelle impostazioni del nodo, il modello e la connessione.",
        "タイルは、全インバーターの太陽光パネル出力・負荷・バッテリー・系統の合計です。値はソーラーノード（ARMOR-SOLAR、機器のそばに置くESP32-S3）がシリアルポート経由でインバーターやバッテリーと通信して送ったもので、Studioは表示するだけなので読み取り専用です。機器は下の「インバーターを追加」で宣言します：名前、読み取るノード、ノード設定内の識別子、モデル、接続方法。",
        "卡片汇总各逆变器的光伏功率、负载、电池和电网功率。读数来自太阳能节点（ARMOR-SOLAR，放在设备旁的 ESP32-S3），它通过串口与逆变器和电池通信并发送所读内容；Studio 只负责显示，因此读数是只读的。设备在下方用“添加逆变器”声明：名称、读取它的节点、它在节点设置中的标识、型号和连接方式。",
        "Os cartões somam a potência dos painéis, a carga, a bateria e a rede entre os seus inversores. As leituras vêm de um nó solar (ARMOR-SOLAR, um ESP32-S3 junto do equipamento) que fala com inversores e baterias pelas portas série e envia o que lê; o Studio só o mostra, por isso as leituras são só de leitura. O equipamento declara-se em baixo com \"Adicionar um inversor\": um nome, o nó que o lê, o seu identificador nas definições do nó, o modelo e como está ligado."] },
    { target: "inv-flow", placement: "bottom",
      t: ["The power flow and the state", "El flujo de energía y el estado", "Der Energiefluss und der Zustand", "Le flux d'énergie et l'état", "Il flusso di energia e lo stato", "電力の流れと状態", "能量流向与状态", "O fluxo de energia e o estado"],
      b: ["The first card draws how the energy moves: panels, inverter, battery, load and grid, with animated lines that follow the real direction. It also shows the mode of the inverter (line, battery or fault). If an inverter is silent, the card turns grey and says \"no data for a while\": check the node and its serial cable first, then the power of the inverter itself. Use \"Show example readings\" to see how it will look with data; nothing is saved.",
        "La primera tarjeta dibuja cómo se mueve la energía: paneles, inversor, batería, carga y red, con líneas animadas que siguen la dirección real. También muestra el modo del inversor (red, batería o fallo). Si un inversor está en silencio, la tarjeta se pone gris y dice \"sin datos desde hace rato\": revisa primero el nodo y su cable serie, luego la alimentación del propio inversor. Usa \"Mostrar lecturas de ejemplo\" para ver cómo quedará con datos; no se guarda nada.",
        "Die erste Karte zeichnet den Energiefluss: Module, Wechselrichter, Batterie, Last und Netz, mit animierten Linien in der echten Richtung. Sie zeigt auch den Modus des Wechselrichters (Netz, Batterie oder Fehler). Schweigt ein Wechselrichter, wird die Karte grau und sagt \"länger keine Daten\": Prüfen Sie zuerst Knoten und seriellen Anschluss, dann die Stromversorgung des Geräts. \"Beispielwerte zeigen\" zeigt das Aussehen mit Daten; nichts wird gespeichert.",
        "La première carte dessine le mouvement de l'énergie : panneaux, onduleur, batterie, charge et réseau, avec des lignes animées dans le sens réel. Elle montre aussi le mode de l'onduleur (secteur, batterie ou défaut). Si un onduleur est muet, la carte devient grise et dit « pas de données depuis un moment » : vérifiez d'abord le nœud et son câble série, puis l'alimentation de l'onduleur. « Afficher des mesures d'exemple » montre le rendu avec des données ; rien n'est enregistré.",
        "La prima scheda disegna come si muove l'energia: pannelli, inverter, batteria, carico e rete, con linee animate nella direzione reale. Mostra anche la modalità dell'inverter (rete, batteria o guasto). Se un inverter è muto, la scheda diventa grigia e dice \"nessun dato da un po'\": controlla prima il nodo e il suo cavo seriale, poi l'alimentazione dell'inverter. \"Mostra letture di esempio\" fa vedere l'aspetto con dei dati; non si salva nulla.",
        "最初のカードは電力の流れを描きます：パネル、インバーター、バッテリー、負荷、系統が、実際の向きに動く線でつながります。インバーターのモード（系統・バッテリー・故障）も表示されます。インバーターが無通信だとカードが灰色になり「しばらくデータなし」と出ます。まずノードとシリアルケーブル、次にインバーター本体の電源を確認してください。「例の値を表示」でデータありの見た目を確認できます（保存はされません）。",
        "第一张卡片绘制能量的流动：光伏板、逆变器、电池、负载和电网，动画线条沿真实方向流动。它还显示逆变器的模式（市电、电池或故障）。如果逆变器沉默，卡片会变灰并显示“有一段时间没有数据”：先检查节点及其串口线，再检查逆变器本身的电源。“显示示例读数”可预览有数据时的样子，不会保存任何内容。",
        "O primeiro cartão desenha como a energia se move: painéis, inversor, bateria, carga e rede, com linhas animadas na direção real. Mostra também o modo do inversor (rede, bateria ou avaria). Se um inversor estiver em silêncio, o cartão fica cinzento e diz \"sem dados há algum tempo\": verifique primeiro o nó e o cabo série, depois a alimentação do próprio inversor. \"Mostrar leituras de exemplo\" mostra o aspeto com dados; nada é guardado."] },
    { target: "inv-gauges", placement: "top",
      t: ["Gauges, LEDs and warnings", "Medidores, LED y avisos", "Messgeräte, LEDs und Warnungen", "Jauges, LED et avertissements", "Indicatori, LED e avvisi", "ゲージ・LED・警告", "仪表、指示灯与警告", "Medidores, LED e avisos"],
      b: ["The gauges show voltage, current, power, temperature and load of the inverter, and the LEDs its states. Under them come the warnings it reports, in plain words. Some models cannot be asked for warnings: then Studio says \"unknown\" and not \"none\", with an explanation on hover. A power marked with ≈ is an estimate (a current input with a nominal voltage) and can be higher than the real consumption.",
        "Los medidores muestran tensión, corriente, potencia, temperatura y carga del inversor, y los LED sus estados. Debajo vienen los avisos que informa, en palabras claras. Algunos modelos no se pueden consultar por avisos: entonces Studio dice \"desconocido\" y no \"ninguno\", con una explicación al pasar el puntero. Una potencia marcada con ≈ es una estimación (una entrada de corriente con una tensión nominal) y puede ser mayor que el consumo real.",
        "Die Messgeräte zeigen Spannung, Strom, Leistung, Temperatur und Last des Wechselrichters, die LEDs seine Zustände. Darunter stehen die gemeldeten Warnungen in einfachen Worten. Bei manchen Modellen lassen sich Warnungen nicht abfragen: Dann sagt Studio \"unbekannt\" statt \"keine\", mit Erklärung beim Überfahren. Eine mit ≈ markierte Leistung ist eine Schätzung (ein Stromeingang mit Nennspannung) und kann höher sein als der echte Verbrauch.",
        "Les jauges montrent tension, courant, puissance, température et charge de l'onduleur, et les LED ses états. Dessous, les avertissements qu'il rapporte, en termes simples. Certains modèles ne peuvent pas être interrogés sur leurs avertissements : Studio dit alors « inconnu » et non « aucun », avec une explication au survol. Une puissance marquée ≈ est une estimation (une entrée de courant avec une tension nominale) et peut dépasser la consommation réelle.",
        "Gli indicatori mostrano tensione, corrente, potenza, temperatura e carico dell'inverter, e i LED i suoi stati. Sotto, gli avvisi che riporta, in parole semplici. Alcuni modelli non si possono interrogare sugli avvisi: allora Studio dice \"sconosciuto\" e non \"nessuno\", con una spiegazione al passaggio del puntatore. Una potenza segnata con ≈ è una stima (un ingresso di corrente con una tensione nominale) e può essere maggiore del consumo reale.",
        "ゲージはインバーターの電圧・電流・電力・温度・負荷を、LEDは状態を示します。その下に、報告された警告が分かりやすい言葉で並びます。モデルによっては警告を問い合わせられず、その場合は「なし」ではなく「不明」と表示し、ポインターを重ねると理由が出ます。「≈」付きの電力は推定値（公称電圧での電流入力）で、実際の消費より大きいことがあります。",
        "仪表显示逆变器的电压、电流、功率、温度和负载，指示灯显示其状态。下方用通俗语言列出它上报的警告。有些型号无法查询警告：此时 Studio 显示“未知”而不是“无”，悬停可看到说明。带 ≈ 的功率是估算值（以标称电压计算的电流输入），可能高于实际用电量。",
        "Os medidores mostram tensão, corrente, potência, temperatura e carga do inversor, e os LED os seus estados. Por baixo vêm os avisos que comunica, em palavras simples. Alguns modelos não permitem consultar avisos: então o Studio diz \"desconhecido\" e não \"nenhum\", com uma explicação ao passar o ponteiro. Uma potência marcada com ≈ é uma estimativa (uma entrada de corrente com uma tensão nominal) e pode ser maior do que o consumo real."] },
    { target: "inv-history", placement: "top",
      t: ["History, energy per day and alarm levels", "Historial, energía por día y niveles de alarma", "Verlauf, Energie pro Tag und Alarmstufen", "Historique, énergie par jour et niveaux d'alarme", "Cronologia, energia al giorno e livelli di allarme", "履歴・1日の発電量・アラーム基準", "历史、每日能量与报警阈值", "Histórico, energia por dia e níveis de alarme"],
      b: ["History charts how the readings changed over the range you pick (the buttons change it). \"Energy per day\" is added up by the server from the readings and kept across restarts, in kilowatt-hours. \"Alarm levels\" sets when an inverter or a battery raises an alarm; each one ends with a small margin so a value on the edge does not flap. A fault raises a HIGH alarm; keep the defaults unless you know why you change them.",
        "El historial dibuja cómo cambiaron las lecturas en el rango que elijas (los botones lo cambian). \"Energía por día\" la suma el servidor a partir de las lecturas y se conserva al reiniciar, en kilovatios-hora. \"Niveles de las alarmas\" fija cuándo un inversor o una batería levanta una alarma; cada una termina con un pequeño margen para que un valor en el borde no oscile. Un fallo levanta una alarma ALTA; deja los valores por defecto salvo que sepas por qué cambiarlos.",
        "Der Verlauf zeichnet, wie sich die Werte im gewählten Bereich änderten (die Tasten ändern ihn). \"Energie pro Tag\" addiert der Server aus den Messwerten und behält sie über Neustarts, in Kilowattstunden. \"Alarmstufen\" legt fest, wann ein Wechselrichter oder eine Batterie einen Alarm auslöst; jeder endet mit kleinem Abstand, damit ein Wert am Rand nicht flattert. Ein Fehler löst einen HOHEN Alarm aus; lassen Sie die Standardwerte, außer Sie wissen, warum.",
        "L'historique trace l'évolution des mesures sur la plage choisie (les boutons la changent). « Énergie par jour » est additionnée par le serveur à partir des mesures et conservée aux redémarrages, en kilowattheures. « Niveaux des alarmes » fixe quand un onduleur ou une batterie lève une alarme ; chacune se termine avec une petite marge pour qu'une valeur en limite ne clignote pas. Un défaut lève une alarme ÉLEVÉE ; gardez les valeurs par défaut sauf raison précise.",
        "La cronologia traccia come sono cambiate le letture nell'intervallo scelto (i pulsanti lo cambiano). \"Energia al giorno\" la somma il server dalle letture e la conserva ai riavvii, in kilowattora. \"Livelli degli allarmi\" fissa quando un inverter o una batteria solleva un allarme; ognuno termina con un piccolo margine perché un valore al limite non oscilli. Un guasto solleva un allarme ALTO; lascia i valori predefiniti salvo motivo preciso.",
        "履歴は選んだ範囲（ボタンで変更）で値がどう変化したかをグラフにします。「1日あたりのエネルギー」はサーバーが値から積算し、再起動後も保持されます（kWh）。「アラームの基準」はインバーターやバッテリーがアラームを上げる条件で、境界付近でばたつかないよう少し余裕を持って解除されます。故障は高アラームになります。理由がなければ初期値のままにしてください。",
        "历史按所选范围（用按钮切换）绘制读数的变化。“每日能量”由服务器根据读数累加，并在重启后保留，单位为千瓦时。“报警阈值”设定逆变器或电池何时触发报警；每项解除时留有小余量，避免临界值反复跳动。故障会触发高级报警；除非知道原因，请保留默认值。",
        "O histórico desenha como as leituras mudaram no intervalo que escolher (os botões mudam-no). \"Energia por dia\" é somada pelo servidor a partir das leituras e conservada nos reinícios, em quilowatts-hora. \"Níveis dos alarmes\" define quando um inversor ou uma bateria levanta um alarme; cada um termina com uma pequena margem para um valor no limite não oscilar. Uma avaria levanta um alarme ALTO; mantenha os valores por defeito salvo se souber porquê alterar."] },
  ],
  batteries: [
    { target: "bat-head", placement: "bottom",
      t: ["Charge, energy and capacity", "Carga, energía y capacidad", "Ladung, Energie und Kapazität", "Charge, énergie et capacité", "Carica, energia e capacità", "充電量・エネルギー・容量", "电量、能量与容量", "Carga, energia e capacidade"],
      b: ["The tiles show the state of charge of the banks, the energy they hold in kWh and their capacity in Ah. The readings come from the solar node that talks to the battery's own management system, and you declare each bank with \"Add a battery\": a name, the node, its identifier, the model and the connection. A bank that has not sent its first reading waits; \"Show example readings\" fills the screen with made-up values to see the layout.",
        "Las fichas muestran el estado de carga de los bancos, la energía que guardan en kWh y su capacidad en Ah. Las lecturas vienen del nodo solar que habla con el sistema de gestión de la propia batería, y cada banco se declara con \"Añadir una batería\": un nombre, el nodo, su identificador, el modelo y la conexión. Un banco que aún no ha enviado su primera lectura espera; \"Mostrar lecturas de ejemplo\" llena la pantalla con valores inventados para ver el aspecto.",
        "Die Kacheln zeigen den Ladezustand der Bänke, die gespeicherte Energie in kWh und die Kapazität in Ah. Die Werte kommen vom Solarknoten, der mit dem Batteriemanagement spricht; jede Bank melden Sie mit \"Batterie hinzufügen\" an: Name, Knoten, Kennung, Modell und Anschluss. Eine Bank ohne erste Messung wartet; \"Beispielwerte zeigen\" füllt den Bildschirm mit erfundenen Werten, um das Aussehen zu sehen.",
        "Les tuiles montrent l'état de charge des bancs, l'énergie stockée en kWh et la capacité en Ah. Les mesures viennent du nœud solaire qui parle au système de gestion de la batterie ; chaque banc se déclare avec « Ajouter une batterie » : un nom, le nœud, son identifiant, le modèle et la connexion. Un banc qui n'a pas envoyé sa première mesure attend ; « Afficher des mesures d'exemple » remplit l'écran de valeurs fictives pour voir la présentation.",
        "Le schede mostrano lo stato di carica dei banchi, l'energia che contengono in kWh e la capacità in Ah. Le letture vengono dal nodo solare che parla con il sistema di gestione della batteria; ogni banco si dichiara con \"Aggiungi una batteria\": un nome, il nodo, il suo identificativo, il modello e la connessione. Un banco che non ha inviato la prima lettura attende; \"Mostra letture di esempio\" riempie lo schermo di valori inventati per vedere l'aspetto.",
        "タイルはバンクの充電状態、蓄えているエネルギー（kWh）、容量（Ah）を示します。値はバッテリー自身の管理システムと通信するソーラーノードから届きます。各バンクは「バッテリーを追加」で宣言します：名前、ノード、識別子、モデル、接続。最初の値が届くまでは待機表示です。「例の値を表示」で架空の値を入れて見た目を確認できます。",
        "卡片显示各电池组的电量状态、所存能量（kWh）和容量（Ah）。读数来自与电池自身管理系统通信的太阳能节点；每个电池组用“添加电池”声明：名称、节点、标识、型号和连接方式。尚未收到第一次读数的电池组处于等待状态；“显示示例读数”会用虚构数值填满页面，便于预览布局。",
        "Os cartões mostram o estado de carga dos bancos, a energia que guardam em kWh e a capacidade em Ah. As leituras vêm do nó solar que fala com o sistema de gestão da própria bateria; cada banco declara-se com \"Adicionar uma bateria\": um nome, o nó, o seu identificador, o modelo e a ligação. Um banco que ainda não enviou a primeira leitura aguarda; \"Mostrar leituras de exemplo\" enche o ecrã de valores inventados para ver o aspeto."] },
    { target: "bat-stack", placement: "bottom",
      t: ["Modules and cells", "Módulos y celdas", "Module und Zellen", "Modules et cellules", "Moduli e celle", "モジュールとセル", "模块与电芯", "Módulos e células"],
      b: ["A bank is made of modules and each module of cells. The top of the card shows the bank's voltage, current, temperature and charge; the module cards below show each module, and \"Cells\" lists its cells one by one so a weak or unbalanced cell stands out. A module that is not present is marked \"not present\". An unbalanced or hot cell is the first sign of an ageing pack: look here before the capacity drops.",
        "Un banco se compone de módulos y cada módulo de celdas. La parte de arriba de la tarjeta muestra tensión, corriente, temperatura y carga del banco; las tarjetas de módulo de debajo muestran cada módulo, y \"Celdas\" lista sus celdas una a una para que una celda débil o desequilibrada destaque. Un módulo que no está presente se marca \"no presente\". Una celda desequilibrada o caliente es la primera señal de un paquete que envejece: mira aquí antes de que caiga la capacidad.",
        "Eine Bank besteht aus Modulen und jedes Modul aus Zellen. Oben auf der Karte stehen Spannung, Strom, Temperatur und Ladung der Bank; die Modulkarten darunter zeigen jedes Modul, und \"Zellen\" listet seine Zellen einzeln, damit eine schwache oder unsymmetrische Zelle auffällt. Ein nicht vorhandenes Modul ist als \"nicht vorhanden\" markiert. Eine unsymmetrische oder heiße Zelle ist das erste Zeichen eines alternden Akkus: Schauen Sie hier, bevor die Kapazität sinkt.",
        "Un banc se compose de modules et chaque module de cellules. Le haut de la carte montre tension, courant, température et charge du banc ; les cartes de module dessous montrent chaque module, et « Cellules » liste ses cellules une à une pour qu'une cellule faible ou déséquilibrée ressorte. Un module absent est marqué « non présent ». Une cellule déséquilibrée ou chaude est le premier signe d'un pack qui vieillit : regardez ici avant que la capacité ne chute.",
        "Un banco è fatto di moduli e ogni modulo di celle. La parte alta della scheda mostra tensione, corrente, temperatura e carica del banco; le schede dei moduli sotto mostrano ogni modulo, e \"Celle\" elenca le sue celle una per una perché una cella debole o sbilanciata risalti. Un modulo non presente è segnato \"non presente\". Una cella sbilanciata o calda è il primo segno di un pacco che invecchia: guarda qui prima che la capacità cali.",
        "バンクはモジュールで、モジュールはセルでできています。カード上部にバンク全体の電圧・電流・温度・充電量が出て、下のモジュールカードに各モジュール、「セル」ではセルを1つずつ一覧にするので、弱いセルやバランスの崩れたセルが目立ちます。存在しないモジュールは「未実装」と表示されます。バランスの崩れや高温のセルは劣化の最初のサインです。容量が落ちる前にここを見ましょう。",
        "电池组由模块组成，每个模块由电芯组成。卡片顶部显示整组的电压、电流、温度和电量；下方的模块卡片显示每个模块，“电芯”会逐个列出电芯，使较弱或不平衡的电芯一目了然。不存在的模块标记为“不存在”。电芯不平衡或过热是电池老化的最早信号：在容量下降之前先看这里。",
        "Um banco é feito de módulos e cada módulo de células. O topo do cartão mostra a tensão, corrente, temperatura e carga do banco; os cartões de módulo por baixo mostram cada módulo, e \"Células\" lista as suas células uma a uma para uma célula fraca ou desequilibrada se destacar. Um módulo que não está presente é marcado \"não presente\". Uma célula desequilibrada ou quente é o primeiro sinal de um conjunto que envelhece: olhe aqui antes de a capacidade cair."] },
    { target: "bat-stack", placement: "top",
      t: ["Module details, cells and the event log", "Detalles del módulo, celdas y registro de eventos", "Moduldetails, Zellen und Ereignisprotokoll", "Détails du module, cellules et journal d'événements", "Dettagli del modulo, celle e registro eventi", "モジュールの詳細・セル・イベントログ", "模块详情、电芯与事件日志", "Detalhes do módulo, células e registo de eventos"],
      b: ["Each module card shows the model the module reports, the versions of its board and software, the number of cells, the charge and discharge current it allows and the speed of its console (an old unit says 19200). Open the fold-outs: the state of health of every cell as the battery's console counts it (the cell it calls abnormal is marked and the fold-out opens by itself), the protection counters above zero (named as the console prints them; their meaning is not official) and the event log that the gateway node reads from the module, newest first and exactly as the console prints it, never translated. Under every alert, two lines say what it means and what to check. The warnings about mixed models are advice from the makers' manuals: the master of a group should be the newest model, only the C, UP and US5000 models are accepted from the 9th module on, and a 24 V model does not share a group with 48 V ones. Everything here is read-only.",
        "Cada tarjeta de módulo muestra el modelo que el módulo informa, las versiones de su placa y de su software, el número de celdas, la corriente de carga y de descarga que permite y la velocidad de su consola (una unidad antigua dice 19200). Abre los desplegables: el estado de salud de cada celda como lo cuenta la consola de la batería (la celda que llama anormal se marca y el desplegable se abre solo), los contadores de protección por encima de cero (con el nombre que les pone la consola; su significado no es oficial) y el registro de eventos que el nodo pasarela lee del módulo, el más reciente primero y tal como lo imprime la consola, sin traducir. Debajo de cada alerta, dos líneas dicen qué significa y qué revisar. Los avisos sobre modelos mezclados son consejos de los manuales de los fabricantes: el maestro de un grupo debería ser el modelo más nuevo, desde el 9.º módulo solo se aceptan los modelos C, UP y US5000, y un modelo de 24 V no comparte grupo con los de 48 V. Todo esto es de solo lectura.",
        "Jede Modulkarte zeigt das vom Modul gemeldete Modell, die Versionen von Platine und Software, die Zellenzahl, den erlaubten Lade- und Entladestrom und die Geschwindigkeit der Konsole (ein altes Gerät meldet 19200). Öffnen Sie die Aufklappbereiche: den Gesundheitszustand jeder Zelle, wie ihn die Konsole der Batterie zählt (die als auffällig bezeichnete Zelle ist markiert und der Bereich öffnet sich von selbst), die Schutzzähler über null (so benannt, wie die Konsole sie ausgibt; ihre Bedeutung ist nicht offiziell) und das Ereignisprotokoll, das der Gateway-Knoten aus dem Modul liest, das neueste zuerst und genau so, wie die Konsole es ausgibt, nie übersetzt. Unter jedem Alarm sagen zwei Zeilen, was er bedeutet und was zu prüfen ist. Die Warnungen zu gemischten Modellen sind Hinweise aus den Handbüchern der Hersteller: Der Master einer Gruppe sollte das neueste Modell sein, ab dem 9. Modul werden nur die Modelle C, UP und US5000 akzeptiert, und ein 24-V-Modell teilt keine Gruppe mit 48-V-Modellen. Alles hier ist schreibgeschützt.",
        "Chaque carte de module montre le modèle que le module annonce, les versions de sa carte et de son logiciel, le nombre de cellules, le courant de charge et de décharge qu'il autorise et la vitesse de sa console (un ancien appareil annonce 19200). Ouvrez les volets : l'état de santé de chaque cellule tel que la console de la batterie le compte (la cellule qu'elle juge anormale est marquée et le volet s'ouvre tout seul), les compteurs de protection au-dessus de zéro (nommés comme la console les imprime ; leur sens n'est pas officiel) et le journal d'événements que le nœud passerelle lit dans le module, le plus récent d'abord et exactement tel que la console l'imprime, jamais traduit. Sous chaque alerte, deux lignes disent ce qu'elle signifie et quoi vérifier. Les avertissements sur les modèles mélangés sont des conseils des manuels des fabricants : le maître d'un groupe doit être le modèle le plus récent, seuls les modèles C, UP et US5000 sont acceptés à partir du 9e module, et un modèle 24 V ne partage pas un groupe avec des 48 V. Tout ici est en lecture seule.",
        "Ogni scheda del modulo mostra il modello che il modulo dichiara, le versioni della sua scheda e del suo software, il numero di celle, la corrente di carica e scarica che consente e la velocità della sua console (un'unità vecchia dice 19200). Apri i riquadri a comparsa: lo stato di salute di ogni cella come lo conta la console della batteria (la cella che chiama anomala è segnata e il riquadro si apre da solo), i contatori di protezione sopra zero (con il nome che la console stampa; il loro significato non è ufficiale) e il registro eventi che il nodo gateway legge dal modulo, il più recente per primo e così come lo stampa la console, mai tradotto. Sotto ogni allarme due righe dicono cosa significa e cosa controllare. Gli avvisi sui modelli mischiati sono consigli dei manuali dei produttori: il master di un gruppo dovrebbe essere il modello più nuovo, dal 9° modulo si accettano solo i modelli C, UP e US5000 e un modello da 24 V non condivide il gruppo con quelli da 48 V. Tutto qui è di sola lettura.",
        "各モジュールのカードには、モジュールが報告するモデル、基板とソフトウェアのバージョン、セル数、許容される充電・放電電流、コンソールの速度（古い機器は19200と表示）が出ます。展開欄を開くと、バッテリーのコンソールが数えるセルごとの健全度（異常とされたセルには印が付き、欄は自動で開きます）、0を超えた保護カウンター（コンソールの表記どおり。意味は公式なものではありません）、そしてゲートウェイノードがモジュールから読み取ったイベントログ（新しい順で、コンソールの出力そのまま、翻訳なし）を確認できます。各アラートの下には、意味と確認すべき点が2行で示されます。混在モデルの警告はメーカーのマニュアルに基づく助言です：グループのマスターは最新のモデルにする、9台目以降はC・UP・US5000のみ、24Vモデルは48Vモデルと同じグループにしない。ここはすべて読み取り専用です。",
        "每个模块卡片显示模块上报的型号、主板和软件版本、电芯数量、允许的充放电电流以及控制台速率（旧设备为 19200）。展开折叠项：电池控制台统计的每个电芯的健康状态（被判为异常的电芯会被标出，折叠项自动展开）、大于零的保护计数器（按控制台打印的名称显示，其含义并非官方说明），以及网关节点从模块读取的事件日志（最新的在前，与控制台输出完全一致，不翻译）。每条警报下方有两行，说明它的含义和该检查什么。关于混用型号的警告来自厂家手册：组内主机应为最新型号，第 9 个模块起只接受 C、UP 和 US5000 型号，24 V 型号不与 48 V 型号同组。这里的一切都是只读的。",
        "Cada cartão de módulo mostra o modelo que o módulo comunica, as versões da sua placa e do seu software, o número de células, a corrente de carga e de descarga que permite e a velocidade da sua consola (uma unidade antiga diz 19200). Abra os painéis expansíveis: o estado de saúde de cada célula como a consola da bateria o conta (a célula que ela considera anormal fica assinalada e o painel abre-se sozinho), os contadores de proteção acima de zero (com o nome que a consola imprime; o seu significado não é oficial) e o registo de eventos que o nó gateway lê do módulo, o mais recente primeiro e tal como a consola o imprime, nunca traduzido. Por baixo de cada alerta, duas linhas dizem o que significa e o que verificar. Os avisos sobre modelos misturados são conselhos dos manuais dos fabricantes: o mestre de um grupo deve ser o modelo mais recente, a partir do 9.º módulo só se aceitam os modelos C, UP e US5000, e um modelo de 24 V não partilha grupo com os de 48 V. Tudo aqui é só de leitura."] },
    { target: "bat-history", placement: "top",
      t: ["History and the 20 % warning", "Historial y el aviso del 20 %", "Verlauf und die 20-%-Warnung", "Historique et l'avertissement à 20 %", "Cronologia e l'avviso al 20 %", "履歴と20%の警告", "历史与 20% 警告", "Histórico e o aviso dos 20 %"],
      b: ["History charts the charge and the voltage over the range you pick. A battery below 20 % of charge raises a warning that ends only when it is back above 30 %, so it does not flap on the edge; a battery that reports an alarm of its own raises a HIGH alarm. The capacity bar shows what is left of the full capacity in Ah. If the charge falls overnight faster than usual, compare it with the load in Inverters.",
        "El historial dibuja la carga y la tensión en el rango que elijas. Una batería por debajo del 20 % de carga levanta un aviso que termina solo cuando vuelve por encima del 30 %, para que no oscile en el borde; una batería que informa de una alarma propia levanta una alarma ALTA. La barra de capacidad muestra lo que queda de la capacidad total en Ah. Si la carga baja por la noche más deprisa de lo normal, compárala con la carga en Inversores.",
        "Der Verlauf zeichnet Ladung und Spannung im gewählten Bereich. Eine Batterie unter 20 % Ladung löst eine Warnung aus, die erst endet, wenn sie wieder über 30 % ist, damit sie am Rand nicht flattert; meldet eine Batterie einen eigenen Alarm, entsteht ein HOHER Alarm. Der Kapazitätsbalken zeigt, was von der Gesamtkapazität in Ah übrig ist. Sinkt die Ladung nachts schneller als üblich, vergleichen Sie mit der Last unter Wechselrichter.",
        "L'historique trace la charge et la tension sur la plage choisie. Une batterie sous 20 % de charge lève un avertissement qui ne se termine qu'au retour au-dessus de 30 %, pour ne pas clignoter en limite ; une batterie qui rapporte sa propre alarme lève une alarme ÉLEVÉE. La barre de capacité montre ce qui reste de la capacité totale en Ah. Si la charge baisse la nuit plus vite que d'habitude, comparez avec la charge dans Onduleurs.",
        "La cronologia traccia carica e tensione nell'intervallo scelto. Una batteria sotto il 20 % di carica solleva un avviso che termina solo quando torna sopra il 30 %, perché non oscilli al limite; una batteria che riporta un allarme proprio solleva un allarme ALTO. La barra della capacità mostra quanto resta della capacità totale in Ah. Se la carica scende di notte più in fretta del solito, confrontala con il carico in Inverter.",
        "履歴は選んだ範囲で充電量と電圧を描きます。充電量が20%を下回ると警告が上がり、境界でばたつかないよう30%を超えるまで続きます。バッテリー自身がアラームを報告した場合は高アラームになります。容量バーは全容量のうち残りをAhで示します。夜間に充電量がいつもより速く減る場合は、インバーターの負荷と見比べてください。",
        "历史按所选范围绘制电量和电压。电量低于 20% 会触发警告，直到回升到 30% 以上才结束，避免在临界点来回跳动；电池自身上报报警时会触发高级报警。容量条显示总容量中剩余的安时数。如果夜间电量下降得比平时快，请与“逆变器”中的负载对比。",
        "O histórico desenha a carga e a tensão no intervalo que escolher. Uma bateria abaixo de 20 % de carga levanta um aviso que só termina quando voltar acima de 30 %, para não oscilar no limite; uma bateria que comunica um alarme próprio levanta um alarme ALTO. A barra de capacidade mostra o que resta da capacidade total em Ah. Se a carga descer à noite mais depressa do que o habitual, compare com a carga em Inversores."] },
  ],
  electrical: [
    { target: "el-head", placement: "bottom",
      t: ["The electrical nodes and their totals", "Los nodos eléctricos y sus totales", "Die Elektroknoten und ihre Summen", "Les nœuds électriques et leurs totaux", "I nodi elettrici e i loro totali", "電気ノードと合計", "电气节点及其汇总", "Os nós elétricos e os seus totais"],
      b: ["An electrical node (ARMOR-ELECTRICAL) is the ESP32 of the panel that measures the lines and reads the switches; this menu shows what it measures, live and read-only. The tiles add up the grid power and energy and count the nodes that answer. If no electrical node has reported yet, the screen tells you what to do: power one on in this network and look for it in the node finder.",
        "Un nodo eléctrico (ARMOR-ELECTRICAL) es el ESP32 del cuadro que mide las líneas y lee los conmutadores; este menú muestra lo que mide, en directo y de solo lectura. Las fichas suman la potencia y la energía de la red y cuentan los nodos que responden. Si ningún nodo eléctrico ha informado aún, la pantalla dice qué hacer: enciende uno en esta red y búscalo en el buscador de nodos.",
        "Ein Elektroknoten (ARMOR-ELECTRICAL) ist der ESP32 im Schaltschrank, der die Leitungen misst und die Schalter liest; dieses Menü zeigt live und schreibgeschützt, was er misst. Die Kacheln addieren Netzleistung und -energie und zählen die antwortenden Knoten. Hat noch kein Elektroknoten berichtet, sagt der Bildschirm, was zu tun ist: einen in diesem Netz einschalten und im Knotensucher suchen.",
        "Un nœud électrique (ARMOR-ELECTRICAL) est l'ESP32 du tableau qui mesure les lignes et lit les commutateurs ; ce menu montre ce qu'il mesure, en direct et en lecture seule. Les tuiles additionnent puissance et énergie du réseau et comptent les nœuds qui répondent. Si aucun nœud électrique n'a encore rapporté, l'écran dit quoi faire : en allumer un sur ce réseau et le chercher dans le détecteur de nœuds.",
        "Un nodo elettrico (ARMOR-ELECTRICAL) è l'ESP32 del quadro che misura le linee e legge i commutatori; questo menu mostra ciò che misura, dal vivo e in sola lettura. Le schede sommano potenza ed energia della rete e contano i nodi che rispondono. Se nessun nodo elettrico ha ancora riferito, la schermata dice cosa fare: accendine uno in questa rete e cercalo nel cercatore di nodi.",
        "電気ノード（ARMOR-ELECTRICAL）は、分電盤の中で回線を計測しスイッチを読むESP32です。このメニューは計測値をライブで読み取り専用に表示します。タイルは系統の電力とエネルギーの合計と、応答しているノード数です。まだ電気ノードから報告がない場合は、この画面が手順を案内します：このネットワークでノードを起動し、ノード検索で探してください。",
        "电气节点（ARMOR-ELECTRICAL）是配电箱里的 ESP32，负责测量线路并读取开关；本菜单只读地实时显示它测到的数据。卡片汇总电网功率和电能，并统计响应的节点数。如果还没有电气节点上报，页面会告诉你该怎么做：在此网络中给一个节点上电，然后在节点查找器中搜索。",
        "Um nó elétrico (ARMOR-ELECTRICAL) é o ESP32 do quadro que mede as linhas e lê os comutadores; este menu mostra o que mede, em direto e só de leitura. Os cartões somam a potência e a energia da rede e contam os nós que respondem. Se nenhum nó elétrico tiver comunicado ainda, o ecrã diz o que fazer: ligue um nesta rede e procure-o no localizador de nós."] },
    { target: "el-channels", placement: "top",
      t: ["Channels: volts, amps, watts and energy", "Canales: voltios, amperios, vatios y energía", "Kanäle: Volt, Ampere, Watt und Energie", "Canaux : volts, ampères, watts et énergie", "Canali: volt, ampere, watt ed energia", "チャンネル：電圧・電流・電力・電力量", "通道：电压、电流、功率与电能", "Canais: volts, amperes, watts e energia"],
      b: ["Each node card lists its channels (the mains, the sub-circuits, the solar side) with volts, amps, watts, kWh, frequency, power factor and state. A mains voltage out of range (about 230 V, from 195 to 253) raises a warning that ends by itself, and so do a meter that raises its own alarm and the loss of the grid input; a latched fault of a contactor is HIGH. Below, the transfer switches show whether each is on the grid or on the backup.",
        "Cada tarjeta de nodo lista sus canales (la red, los subcircuitos, el lado solar) con voltios, amperios, vatios, kWh, frecuencia, factor de potencia y estado. Una tensión de red fuera de rango (unos 230 V, de 195 a 253) levanta un aviso que termina solo, igual que un contador que levanta su propia alarma y la pérdida de la entrada de red; un fallo enclavado de un contactor es ALTO. Debajo, los conmutadores de transferencia muestran si cada uno está en la red o en el respaldo.",
        "Jede Knotenkarte listet ihre Kanäle (Netz, Unterkreise, Solarseite) mit Volt, Ampere, Watt, kWh, Frequenz, Leistungsfaktor und Zustand. Eine Netzspannung außerhalb des Bereichs (etwa 230 V, von 195 bis 253) löst eine Warnung aus, die von selbst endet, ebenso ein Zähler mit eigenem Alarm und der Verlust des Netzeingangs; ein verklemmter Schützfehler ist HOCH. Darunter zeigen die Umschalter, ob jeder am Netz oder am Backup hängt.",
        "Chaque carte de nœud liste ses canaux (le secteur, les sous-circuits, le côté solaire) avec volts, ampères, watts, kWh, fréquence, facteur de puissance et état. Une tension secteur hors plage (environ 230 V, de 195 à 253) lève un avertissement qui se termine seul, de même qu'un compteur qui lève sa propre alarme et la perte de l'entrée réseau ; un défaut verrouillé d'un contacteur est ÉLEVÉ. Dessous, les inverseurs de source montrent si chacun est sur le réseau ou sur le secours.",
        "Ogni scheda di nodo elenca i suoi canali (la rete, i sottocircuiti, il lato solare) con volt, ampere, watt, kWh, frequenza, fattore di potenza e stato. Una tensione di rete fuori intervallo (circa 230 V, da 195 a 253) solleva un avviso che termina da solo, come un contatore che solleva un allarme proprio e la perdita dell'ingresso di rete; un guasto bloccato di un contattore è ALTO. Sotto, i commutatori di trasferimento mostrano se ciascuno è sulla rete o sul backup.",
        "各ノードカードに、チャンネル（商用電源、サブ回路、太陽光側）が電圧・電流・電力・kWh・周波数・力率・状態付きで並びます。電源電圧が範囲外（約230V、195〜253V）になると警告が上がり自動で解除されます。メーター自身のアラームや系統入力の喪失も同様で、接触器のラッチ故障は高アラームです。その下の切替スイッチは、それぞれが系統側か予備側かを示します。",
        "每个节点卡片列出其通道（市电、子回路、光伏侧），含电压、电流、功率、kWh、频率、功率因数和状态。市电电压超出范围（约 230 V，195 至 253）会触发可自动解除的警告，电表自身报警和电网输入丢失同理；接触器的锁定故障为高级。下方的切换开关显示每个开关接在电网还是备用电源上。",
        "Cada cartão de nó lista os seus canais (a rede, os subcircuitos, o lado solar) com volts, amperes, watts, kWh, frequência, fator de potência e estado. Uma tensão de rede fora de intervalo (cerca de 230 V, de 195 a 253) levanta um aviso que termina sozinho, tal como um contador que levanta um alarme próprio e a perda da entrada de rede; uma avaria presa de um contactor é ALTA. Por baixo, os comutadores de transferência mostram se cada um está na rede ou no reserva."] },
    { target: "el-energy", placement: "top",
      t: ["Energy per day", "Energía por día", "Energie pro Tag", "Énergie par jour", "Energia al giorno", "1日あたりの電力量", "每日电能", "Energia por dia"],
      b: ["This card adds up, for the last week, what the meter of each channel counted. It adds only the difference between readings, so a meter that wraps at 9,999.99 kWh or starts again from zero after a power cut does not make a negative day or count its whole total again; the day it happens is marked. Use it to see which circuit uses most and whether the week was normal.",
        "Esta tarjeta suma, para la última semana, lo que contó el contador de cada canal. Suma solo la diferencia entre lecturas, así que un contador que da la vuelta en 9.999,99 kWh o que vuelve a cero tras un corte no hace un día negativo ni cuenta de nuevo todo su total; el día en que ocurre queda marcado. Sirve para ver qué circuito gasta más y si la semana fue normal.",
        "Diese Karte addiert für die letzte Woche, was der Zähler jedes Kanals gezählt hat. Sie addiert nur die Differenz zwischen Messwerten, sodass ein Zähler, der bei 9.999,99 kWh überläuft oder nach einem Stromausfall bei null beginnt, keinen negativen Tag erzeugt und nicht seinen Gesamtstand erneut zählt; der betroffene Tag ist markiert. So sehen Sie, welcher Kreis am meisten verbraucht und ob die Woche normal war.",
        "Cette carte additionne, pour la dernière semaine, ce qu'a compté le compteur de chaque canal. Elle n'ajoute que la différence entre mesures : un compteur qui repasse à zéro à 9 999,99 kWh ou après une coupure ne fait pas de jour négatif et ne recompte pas tout son total ; le jour concerné est marqué. Utile pour voir quel circuit consomme le plus et si la semaine était normale.",
        "Questa scheda somma, per l'ultima settimana, ciò che ha contato il contatore di ogni canale. Somma solo la differenza tra le letture, quindi un contatore che riparte da 9.999,99 kWh o da zero dopo un'interruzione non crea un giorno negativo né conta di nuovo tutto il totale; il giorno in cui succede è segnato. Serve a vedere quale circuito consuma di più e se la settimana è stata normale.",
        "直近1週間について、各チャンネルのメーターが数えた量を日ごとに合計します。読み値の差分だけを加算するので、9,999.99kWhで桁あふれしたり停電後にゼロから再開したメーターでも、マイナスの日や全体の二重カウントは起きません（該当日には印が付きます）。どの回路が一番使っているか、今週が普通だったかを見るのに便利です。",
        "此卡片汇总最近一周各通道电表所计的电量。它只累加读数之间的差值，所以电表在 9,999.99 kWh 回零或断电后从零重新开始，也不会出现负数的一天，更不会把总数重复计算；发生这种情况的那一天会被标记。可用它看哪条回路用电最多，以及这一周是否正常。",
        "Este cartão soma, para a última semana, o que o contador de cada canal contou. Soma apenas a diferença entre leituras, por isso um contador que reinicia aos 9.999,99 kWh ou volta a zero após um corte não faz um dia negativo nem conta de novo todo o seu total; o dia em que acontece fica marcado. Serve para ver que circuito gasta mais e se a semana foi normal."] },
    { target: "el-devices", placement: "top",
      t: ["Devices of the house that measure or switch", "Dispositivos de la casa que miden o conmutan", "Geräte des Hauses, die messen oder schalten", "Appareils de la maison qui mesurent ou commutent", "Dispositivi della casa che misurano o commutano", "計測・切替ができる家のデバイス", "可测量或切换的住宅设备", "Dispositivos da casa que medem ou comutam"],
      b: ["Zigbee and other devices that measure or switch electricity (plugs, breakers, lights, meters) appear here with what they say. They are added in the Devices menu; here you can switch the ones that can be switched, and Studio asks before it does. If the diagram of the Electrical Designer has its elements bound to nodes, the live values are drawn on it. Mistake: switching a circuit that feeds the router.",
        "Los dispositivos Zigbee y otros que miden o conmutan electricidad (enchufes, automáticos, luces, medidores) aparecen aquí con lo que dicen. Se añaden en el menú Dispositivos; aquí puedes conmutar los que se pueden, y Studio pregunta antes de hacerlo. Si el esquema del Diseñador eléctrico tiene sus elementos ligados a nodos, los valores en vivo se dibujan sobre él. Error: conmutar un circuito que alimenta el router.",
        "Zigbee- und andere Geräte, die Strom messen oder schalten (Steckdosen, Sicherungen, Lichter, Zähler), erscheinen hier mit dem, was sie melden. Sie werden im Menü Geräte hinzugefügt; hier schalten Sie die schaltbaren, und Studio fragt vorher. Sind die Elemente im Schaltplan des Elektro-Designers an Knoten gebunden, werden die Live-Werte darauf gezeichnet. Fehler: einen Kreis schalten, der den Router speist.",
        "Les appareils Zigbee et autres qui mesurent ou commutent l'électricité (prises, disjoncteurs, lumières, compteurs) apparaissent ici avec ce qu'ils disent. Ils s'ajoutent dans le menu Appareils ; ici vous commutez ceux qui le peuvent, et Studio demande d'abord. Si les éléments du schéma du concepteur électrique sont liés à des nœuds, les valeurs en direct y sont dessinées. Erreur : couper un circuit qui alimente le routeur.",
        "I dispositivi Zigbee e altri che misurano o commutano elettricità (prese, interruttori, luci, contatori) compaiono qui con ciò che dicono. Si aggiungono nel menu Dispositivi; qui puoi commutare quelli commutabili, e Studio chiede prima. Se gli elementi dello schema del progettista elettrico sono legati ai nodi, i valori dal vivo vi sono disegnati sopra. Errore: commutare un circuito che alimenta il router.",
        "電力を計測・切替するZigbeeなどのデバイス（プラグ、ブレーカー、照明、メーター）が、報告内容とともにここに出ます。追加は「デバイス」メニューで行い、ここでは切替可能なものを操作できます（Studioが先に確認します）。電気設計図の要素をノードに紐付けてあると、ライブ値がその上に描かれます。ルーターの電源回路を切ってしまう失敗に注意。",
        "测量或切换用电的 Zigbee 等设备（插座、断路器、灯、电表）会连同它们上报的内容显示在这里。它们在“设备”菜单中添加；这里可以切换可切换的设备，Studio 会先询问。如果电气设计器图中的元素已绑定到节点，实时数值会画在图上。常见错误：切断了给路由器供电的回路。",
        "Os dispositivos Zigbee e outros que medem ou comutam eletricidade (fichas, disjuntores, luzes, contadores) aparecem aqui com o que dizem. Adicionam-se no menu Dispositivos; aqui pode comutar os que se podem comutar, e o Studio pergunta antes. Se os elementos do esquema do Desenhador elétrico estiverem ligados a nós, os valores em direto são desenhados sobre ele. Erro: comutar um circuito que alimenta o router."] },
  ],
  devices: [
    { target: "dev-head", placement: "bottom",
      t: ["Add a device", "Añadir un dispositivo", "Ein Gerät hinzufügen", "Ajouter un appareil", "Aggiungere un dispositivo", "デバイスを追加する", "添加设备", "Adicionar um dispositivo"],
      b: ["The counters show your devices, those online and those with a problem. \"Add a device\" opens the form: a name, the room or zone, the kind (door or window contact, motion, smoke, CO, gas, water leak, glass break, vibration, panic button, plug, light...) and how it talks to A.R.M.O.R.: through MQTT topics (state, command, availability), through web addresses (on, off, toggle) or through a node. The simplest start is a Zigbee sensor already paired to the server.",
        "Los contadores muestran tus dispositivos, los que están en línea y los que tienen un problema. \"Añadir un dispositivo\" abre el formulario: un nombre, la habitación o zona, el tipo (contacto de puerta o ventana, movimiento, humo, CO, gas, fuga de agua, rotura de cristal, vibración, botón de pánico, enchufe, luz...) y cómo habla con A.R.M.O.R.: por topics MQTT (estado, orden, disponibilidad), por direcciones web (encender, apagar, alternar) o por un nodo. Lo más simple para empezar es un sensor Zigbee ya emparejado con el servidor.",
        "Die Zähler zeigen Ihre Geräte, die online sind und die mit einem Problem. \"Gerät hinzufügen\" öffnet das Formular: Name, Raum oder Zone, Art (Tür- oder Fensterkontakt, Bewegung, Rauch, CO, Gas, Wasserleck, Glasbruch, Vibration, Panikknopf, Steckdose, Licht...) und wie es mit A.R.M.O.R. spricht: über MQTT-Topics (Zustand, Befehl, Verfügbarkeit), über Webadressen (ein, aus, umschalten) oder über einen Knoten. Am einfachsten beginnen Sie mit einem schon gekoppelten Zigbee-Sensor.",
        "Les compteurs montrent vos appareils, ceux en ligne et ceux en difficulté. « Ajouter un appareil » ouvre le formulaire : un nom, la pièce ou zone, le type (contact de porte ou fenêtre, mouvement, fumée, CO, gaz, fuite d'eau, bris de vitre, vibration, bouton panique, prise, lumière...) et comment il parle à A.R.M.O.R. : par topics MQTT (état, commande, disponibilité), par adresses web (marche, arrêt, bascule) ou par un nœud. Le plus simple pour commencer : un capteur Zigbee déjà appairé au serveur.",
        "I contatori mostrano i tuoi dispositivi, quelli online e quelli con un problema. \"Aggiungi un dispositivo\" apre il modulo: un nome, la stanza o zona, il tipo (contatto porta o finestra, movimento, fumo, CO, gas, perdita d'acqua, rottura vetri, vibrazione, pulsante di panico, presa, luce...) e come parla con A.R.M.O.R.: tramite topic MQTT (stato, comando, disponibilità), tramite indirizzi web (accendi, spegni, alterna) o tramite un nodo. Il modo più semplice per iniziare è un sensore Zigbee già abbinato al server.",
        "カウンターには、デバイスの総数・オンライン数・問題のある数が出ます。「デバイスを追加」でフォームが開き、名前、部屋またはゾーン、種類（ドア／窓センサー、人感、煙、CO、ガス、水漏れ、ガラス破壊、振動、非常ボタン、プラグ、照明など）、そしてA.R.M.O.R.との通信方法を選びます：MQTTトピック（状態・コマンド・可用性）、Webアドレス（オン・オフ・切替）、またはノード経由。最も簡単なのは、サーバーにペアリング済みのZigbeeセンサーです。",
        "计数器显示你的设备总数、在线数和有问题的数量。“添加设备”打开表单：名称、房间或分区、类型（门窗磁、移动、烟雾、CO、燃气、漏水、玻璃破碎、震动、紧急按钮、插座、灯等），以及它与 A.R.M.O.R. 的通信方式：MQTT 主题（状态、指令、可用性）、网址（开、关、切换）或通过节点。最简单的入门是一个已与服务器配对的 Zigbee 传感器。",
        "Os contadores mostram os seus dispositivos, os ligados e os que têm um problema. \"Adicionar um dispositivo\" abre o formulário: um nome, a divisão ou zona, o tipo (contacto de porta ou janela, movimento, fumo, CO, gás, fuga de água, quebra de vidro, vibração, botão de pânico, ficha, luz...) e como fala com o A.R.M.O.R.: por tópicos MQTT (estado, comando, disponibilidade), por endereços web (ligar, desligar, alternar) ou por um nó. O mais simples para começar é um sensor Zigbee já emparelhado com o servidor."] },
    { target: "dev-filters", placement: "bottom",
      t: ["Find a device", "Encontrar un dispositivo", "Ein Gerät finden", "Trouver un appareil", "Trovare un dispositivo", "デバイスを探す", "查找设备", "Encontrar um dispositivo"],
      b: ["The buttons show everything, only the sensors, only the actuators (what can be switched) or only the ones with a problem, and the search box finds a device by name. With dozens of devices the Problems filter is the fastest: it lists what stopped answering or is triggered, which is usually a flat battery, a lost signal or something that really happened.",
        "Los botones muestran todo, solo los sensores, solo los actuadores (lo que se puede conmutar) o solo los que tienen un problema, y el buscador encuentra un dispositivo por nombre. Con decenas de dispositivos el filtro Problemas es el más rápido: lista lo que dejó de responder o está disparado, que suele ser una pila agotada, una señal perdida o algo que realmente ha pasado.",
        "Die Knöpfe zeigen alles, nur die Sensoren, nur die Aktoren (was sich schalten lässt) oder nur die mit einem Problem, und die Suche findet ein Gerät per Namen. Bei Dutzenden Geräten ist der Filter Probleme am schnellsten: Er listet, was nicht mehr antwortet oder ausgelöst ist, meist eine leere Batterie, verlorenes Signal oder etwas, das wirklich passiert ist.",
        "Les boutons montrent tout, seulement les capteurs, seulement les actionneurs (ce qui peut être commuté) ou seulement ceux en difficulté, et la recherche trouve un appareil par son nom. Avec des dizaines d'appareils, le filtre Problèmes est le plus rapide : il liste ce qui ne répond plus ou est déclenché, souvent une pile à plat, un signal perdu ou quelque chose qui s'est vraiment produit.",
        "I pulsanti mostrano tutto, solo i sensori, solo gli attuatori (ciò che si può commutare) o solo quelli con un problema, e la ricerca trova un dispositivo per nome. Con decine di dispositivi il filtro Problemi è il più rapido: elenca ciò che ha smesso di rispondere o è scattato, di solito una batteria scarica, un segnale perso o qualcosa che è successo davvero.",
        "ボタンで「すべて」「センサーのみ」「アクチュエーター（切替できるもの）のみ」「問題ありのみ」に絞り込め、検索欄で名前から探せます。デバイスが数十台あるときは「問題あり」が最速で、応答しなくなったものや作動中のもの（電池切れ、電波喪失、または本当に起きた出来事）が並びます。",
        "按钮可显示全部、仅传感器、仅执行器（可切换的设备）或仅有问题的设备，搜索框可按名称查找设备。设备很多时，“问题”筛选最快：它列出不再响应或已触发的设备，通常是电池耗尽、信号丢失，或确实发生了什么事。",
        "Os botões mostram tudo, só os sensores, só os atuadores (o que se pode comutar) ou só os que têm um problema, e a pesquisa encontra um dispositivo pelo nome. Com dezenas de dispositivos o filtro Problemas é o mais rápido: lista o que deixou de responder ou está disparado, normalmente uma pilha gasta, um sinal perdido ou algo que realmente aconteceu."] },
    { target: "dev-grid", placement: "top",
      t: ["A device card", "La tarjeta de un dispositivo", "Die Karte eines Geräts", "La carte d'un appareil", "La scheda di un dispositivo", "デバイスカード", "设备卡片", "O cartão de um dispositivo"],
      b: ["Each card has the colour of its kind, its state, its protocol and when it was last seen. Actuators (plugs, lights, locks) have command buttons that switch them. The kind decides when it raises an alarm: smoke, gas and water always, door and motion only while the system is armed. \"Test: trigger\" and \"Test: clear\" set the state by hand to try the alarm and the automations without touching the real device; do not forget to clear.",
        "Cada tarjeta lleva el color de su tipo, su estado, su protocolo y cuándo se vio por última vez. Los actuadores (enchufes, luces, cerraduras) tienen botones de orden que los conmutan. El tipo decide cuándo levanta una alarma: humo, gas y agua siempre, puerta y movimiento solo con el sistema armado. \"Prueba: disparar\" y \"Prueba: limpiar\" fijan el estado a mano para probar la alarma y las automatizaciones sin tocar el dispositivo real; no olvides limpiar.",
        "Jede Karte hat die Farbe ihrer Art, ihren Zustand, ihr Protokoll und den Zeitpunkt der letzten Meldung. Aktoren (Steckdosen, Lichter, Schlösser) haben Befehlsknöpfe zum Schalten. Die Art entscheidet, wann ein Alarm entsteht: Rauch, Gas und Wasser immer, Tür und Bewegung nur bei scharfem System. \"Test: auslösen\" und \"Test: zurücksetzen\" setzen den Zustand von Hand, um Alarm und Automationen ohne das echte Gerät zu testen; vergessen Sie das Zurücksetzen nicht.",
        "Chaque carte a la couleur de son type, son état, son protocole et sa dernière apparition. Les actionneurs (prises, lumières, serrures) ont des boutons de commande. Le type décide quand une alarme est levée : fumée, gaz et eau toujours, porte et mouvement seulement système armé. « Test : déclencher » et « Test : effacer » fixent l'état à la main pour essayer l'alarme et les automatisations sans toucher l'appareil réel ; n'oubliez pas d'effacer.",
        "Ogni scheda ha il colore del suo tipo, lo stato, il protocollo e quando è stato visto l'ultima volta. Gli attuatori (prese, luci, serrature) hanno pulsanti di comando che li commutano. Il tipo decide quando solleva un allarme: fumo, gas e acqua sempre, porta e movimento solo a sistema inserito. \"Prova: attiva\" e \"Prova: azzera\" impostano lo stato a mano per provare l'allarme e le automazioni senza toccare il dispositivo reale; non dimenticare di azzerare.",
        "各カードは種類の色、状態、プロトコル、最終受信時刻を表示します。アクチュエーター（プラグ・照明・鍵）には切替用のコマンドボタンがあります。アラームが上がる条件は種類で決まり、煙・ガス・水は常時、ドア・人感は警戒中のみです。「テスト：作動」「テスト：解除」で状態を手動設定し、実機に触れずにアラームやオートメーションを試せます。解除を忘れずに。",
        "每张卡片带有其类型的颜色、状态、协议和最后一次上报的时间。执行器（插座、灯、门锁）有可切换的指令按钮。类型决定何时触发报警：烟雾、燃气和漏水始终触发，门和移动仅在系统布防时触发。“测试：触发”和“测试：清除”可手动设置状态，在不碰真实设备的情况下测试报警和自动化；别忘了清除。",
        "Cada cartão tem a cor do seu tipo, o estado, o protocolo e quando foi visto pela última vez. Os atuadores (fichas, luzes, fechaduras) têm botões de comando que os comutam. O tipo decide quando levanta um alarme: fumo, gás e água sempre, porta e movimento só com o sistema armado. \"Teste: disparar\" e \"Teste: limpar\" definem o estado à mão para experimentar o alarme e as automatizações sem tocar no dispositivo real; não se esqueça de limpar."] },
    { target: "dev-head", placement: "bottom",
      t: ["Offline, assumed state and placing it on the site", "Desconexión, estado supuesto y colocación en el sitio", "Offline, angenommener Zustand und Platz im Standort", "Hors ligne, état supposé et placement sur le site", "Offline, stato presunto e posizione nel sito", "オフライン・想定状態・サイトへの配置", "离线、假定状态与在场地中的位置", "Desligado, estado presumido e colocação no local"],
      b: ["If a device is silent for its \"expected interval\" it counts as offline; 0 means never. For devices that never say what they did, \"assume the state after a command\" lets Studio assume the command worked. The payload mapping says which field of the device's JSON message holds each value. Each device can be placed on the site design so you see where it is, and it can be the trigger or the target of an automation.",
        "Si un dispositivo calla durante su \"intervalo esperado\" cuenta como desconectado; 0 significa nunca. Para dispositivos que nunca dicen lo que hicieron, \"suponer el estado tras una orden\" permite que Studio dé por buena la orden. El mapeo del mensaje dice qué campo del JSON del dispositivo contiene cada valor. Cada dispositivo puede colocarse en el diseño del sitio para ver dónde está, y puede ser el disparador o el destino de una automatización.",
        "Schweigt ein Gerät über sein \"erwartetes Intervall\", gilt es als offline; 0 heißt nie. Bei Geräten, die nie melden, was sie taten, lässt \"Zustand nach Befehl annehmen\" Studio den Befehl als gelungen ansehen. Die Feldzuordnung sagt, welches Feld der JSON-Nachricht des Geräts welchen Wert enthält. Jedes Gerät lässt sich im Standortentwurf platzieren, und es kann Auslöser oder Ziel einer Automation sein.",
        "Si un appareil se tait pendant son « intervalle attendu », il compte comme hors ligne ; 0 signifie jamais. Pour les appareils qui ne disent jamais ce qu'ils ont fait, « supposer l'état après une commande » laisse Studio considérer la commande comme réussie. Le mappage dit quel champ du JSON de l'appareil contient chaque valeur. Chaque appareil peut être placé sur le plan du site pour voir où il est, et il peut être le déclencheur ou la cible d'une automatisation.",
        "Se un dispositivo tace per il suo \"intervallo atteso\" conta come offline; 0 significa mai. Per i dispositivi che non dicono mai cosa hanno fatto, \"presumi lo stato dopo un comando\" fa considerare riuscito il comando. La mappatura dice quale campo del JSON del dispositivo contiene ogni valore. Ogni dispositivo può essere posto nel progetto del sito per vedere dov'è, e può essere l'innesco o il bersaglio di un'automazione.",
        "「想定間隔」の間デバイスから何も来ないとオフライン扱いになります（0は無効）。実行結果を返さないデバイスには「コマンド後の状態を想定」を使うと、Studioがコマンド成功とみなします。ペイロードのマッピングは、デバイスのJSONメッセージのどのフィールドがどの値かを指定します。各デバイスはサイト設計に配置して場所を確認でき、オートメーションのトリガーにも対象にもなります。",
        "如果设备在其“预期间隔”内没有任何消息，就算离线；0 表示永不判定。对于从不回报动作结果的设备，“指令后假定状态”会让 Studio 认为指令已成功。载荷映射说明设备 JSON 消息中哪个字段对应哪个值。每个设备都可以放到场地设计中查看位置，并可作为自动化的触发条件或目标。",
        "Se um dispositivo se calar durante o seu \"intervalo esperado\" conta como desligado; 0 significa nunca. Para dispositivos que nunca dizem o que fizeram, \"presumir o estado após um comando\" faz o Studio dar o comando por bem-sucedido. O mapeamento diz que campo do JSON do dispositivo contém cada valor. Cada dispositivo pode ser colocado no desenho do local para ver onde está, e pode ser o disparador ou o alvo de uma automatização."] },
  ],
  automations: [
    { target: "auto-head", placement: "bottom",
      t: ["New automation and the templates", "Nueva automatización y las plantillas", "Neue Automation und die Vorlagen", "Nouvelle automatisation et les modèles", "Nuova automazione e i modelli", "新規オートメーションとテンプレート", "新建自动化与模板", "Nova automatização e os modelos"],
      b: ["\"New automation\" opens the builder. Rules have the form \"when this happens, do that\": a smoke alarm switches on the lights, a door opened while armed sounds a siren, an intrusion sends you a notice. The form offers templates (smoke, intrusion, door) that fill the rule for you: start from one and change what you need. Each automation runs at most a few times per minute, so a flapping sensor cannot flood you.",
        "\"Nueva automatización\" abre el constructor. Las reglas tienen la forma \"cuando ocurre esto, haz aquello\": una alarma de humo enciende las luces, una puerta abierta con el sistema armado hace sonar una sirena, una intrusión te envía un aviso. El formulario ofrece plantillas (humo, intrusión, puerta) que rellenan la regla: parte de una y cambia lo que necesites. Cada automatización se ejecuta como mucho unas pocas veces por minuto, así que un sensor inestable no te inunda.",
        "\"Neue Automation\" öffnet den Baukasten. Regeln haben die Form \"wenn das passiert, tue jenes\": Ein Rauchalarm schaltet das Licht ein, eine offene Tür bei scharfem System lässt eine Sirene heulen, ein Einbruch schickt Ihnen eine Meldung. Das Formular bietet Vorlagen (Rauch, Einbruch, Tür), die die Regel ausfüllen: Beginnen Sie mit einer und ändern Sie, was nötig ist. Jede Automation läuft höchstens ein paar Mal pro Minute, ein flatternder Sensor überflutet Sie also nicht.",
        "« Nouvelle automatisation » ouvre le constructeur. Les règles ont la forme « quand ceci arrive, faire cela » : une alarme fumée allume les lumières, une porte ouverte système armé fait sonner une sirène, une intrusion vous envoie un avis. Le formulaire propose des modèles (fumée, intrusion, porte) qui remplissent la règle : partez de l'un d'eux et changez ce qu'il faut. Chaque automatisation s'exécute au plus quelques fois par minute, donc un capteur instable ne vous inonde pas.",
        "\"Nuova automazione\" apre il costruttore. Le regole hanno la forma \"quando accade questo, fai quello\": un allarme fumo accende le luci, una porta aperta a sistema inserito fa suonare una sirena, un'intrusione ti invia un avviso. Il modulo offre modelli (fumo, intrusione, porta) che compilano la regola: parti da uno e cambia ciò che serve. Ogni automazione gira al massimo poche volte al minuto, così un sensore instabile non ti sommerge.",
        "「新規オートメーション」でビルダーが開きます。ルールは「これが起きたら、あれをする」の形です：煙警報で照明を点灯、警戒中にドアが開いたらサイレン、侵入があれば通知。煙・侵入・ドアのテンプレートでルールが自動入力されるので、1つ選んで必要な部分を変えましょう。各オートメーションは1分間に数回までしか実行されないため、センサーがばたついても通知が殺到しません。",
        "“新建自动化”会打开构建器。规则的形式是“当发生这件事时，做那件事”：烟雾报警时开灯，布防时门被打开就让警笛鸣响，入侵时给你发通知。表单提供模板（烟雾、入侵、门）可自动填好规则：选一个再修改所需部分。每条自动化每分钟最多执行几次，因此抖动的传感器不会让你被消息淹没。",
        "\"Nova automatização\" abre o construtor. As regras têm a forma \"quando isto acontece, faça aquilo\": um alarme de fumo acende as luzes, uma porta aberta com o sistema armado faz tocar uma sirene, uma intrusão envia-lhe um aviso. O formulário oferece modelos (fumo, intrusão, porta) que preenchem a regra: parta de um e altere o que precisar. Cada automatização corre no máximo umas poucas vezes por minuto, por isso um sensor instável não o inunda."] },
    { target: "auto-form", placement: "left",
      t: ["WHEN: the trigger and the mode", "CUANDO: el disparador y el modo", "WENN: der Auslöser und der Modus", "QUAND : le déclencheur et le mode", "QUANDO: l'innesco e la modalità", "いつ：トリガーとモード", "当：触发条件与模式", "QUANDO: o disparador e o modo"],
      b: ["Give the rule a name and choose WHEN: a device, a camera or a radar node reports something, or the system becomes armed or disarmed. Optionally add \"and the system is\": in any mode, only while armed or only while disarmed. Besides \"a device reaches a state\", a trigger can be a threshold: a reading goes above or below a value, for example a temperature over 30 or a battery under 20.",
        "Pon nombre a la regla y elige CUANDO: un dispositivo, una cámara o un nodo de radar informa de algo, o el sistema pasa a armado o desarmado. Opcionalmente añade \"y el sistema está\": en cualquier modo, solo armado o solo desarmado. Además de \"un dispositivo alcanza un estado\", el disparador puede ser un umbral: una lectura sube por encima o baja por debajo de un valor, por ejemplo una temperatura sobre 30 o una batería bajo 20.",
        "Geben Sie der Regel einen Namen und wählen Sie WENN: Ein Gerät, eine Kamera oder ein Radarknoten meldet etwas, oder das System wird scharf oder unscharf. Optional \"und das System ist\": in jedem Modus, nur scharf oder nur unscharf. Neben \"ein Gerät erreicht einen Zustand\" kann der Auslöser ein Schwellwert sein: Ein Messwert steigt über oder fällt unter einen Wert, zum Beispiel Temperatur über 30 oder Batterie unter 20.",
        "Donnez un nom à la règle et choisissez QUAND : un appareil, une caméra ou un nœud radar signale quelque chose, ou le système passe armé ou désarmé. Ajoutez au besoin « et le système est » : dans tous les modes, seulement armé ou seulement désarmé. Outre « un appareil atteint un état », le déclencheur peut être un seuil : une mesure dépasse ou passe sous une valeur, par exemple une température au-dessus de 30 ou une batterie sous 20.",
        "Dai un nome alla regola e scegli QUANDO: un dispositivo, una telecamera o un nodo radar riferisce qualcosa, oppure il sistema diventa inserito o disinserito. Facoltativamente aggiungi \"e il sistema è\": in qualsiasi modalità, solo inserito o solo disinserito. Oltre a \"un dispositivo raggiunge uno stato\", l'innesco può essere una soglia: una lettura sale sopra o scende sotto un valore, ad esempio una temperatura oltre 30 o una batteria sotto 20.",
        "ルールに名前を付け、「いつ」を選びます：デバイス・カメラ・レーダーノードが何かを報告したとき、またはシステムが警戒／解除になったとき。必要なら「かつシステムが」で、どのモード／警戒中のみ／解除中のみを指定します。「デバイスがある状態になる」のほか、しきい値（温度が30を超える、バッテリーが20を下回るなど）もトリガーにできます。",
        "给规则起个名字并选择“当”：某个设备、摄像头或雷达节点上报了某事，或系统变为布防或撤防。还可添加“并且系统处于”：任何模式、仅布防时或仅撤防时。除了“设备达到某状态”，触发条件也可以是阈值：读数高于或低于某个值，例如温度超过 30 或电池低于 20。",
        "Dê um nome à regra e escolha QUANDO: um dispositivo, uma câmara ou um nó de radar comunica algo, ou o sistema passa a armado ou desarmado. Opcionalmente acrescente \"e o sistema está\": em qualquer modo, só armado ou só desarmado. Além de \"um dispositivo atinge um estado\", o disparador pode ser um limiar: uma leitura sobe acima ou desce abaixo de um valor, por exemplo uma temperatura acima de 30 ou uma bateria abaixo de 20."] },
    { target: "auto-form", placement: "left",
      t: ["THEN: the actions", "ENTONCES: las acciones", "DANN: die Aktionen", "ALORS : les actions", "ALLORA: le azioni", "そのとき：アクション", "则：动作", "ENTÃO: as ações"],
      b: ["Add one or more actions: switch a device on or off, or send the alarm notification (MQTT and webhook). An action on a device can undo itself with \"then back after (seconds)\", which returns it to its previous state after that time; 0 leaves it as it is. A common mistake is to switch something on in a rule and never switch it off: set the return time or write the opposite rule.",
        "Añade una o más acciones: encender o apagar un dispositivo, o enviar la notificación de alarma (MQTT y webhook). Una acción sobre un dispositivo puede deshacerse sola con \"luego volver tras (segundos)\", que lo devuelve a su estado anterior pasado ese tiempo; 0 lo deja como está. Un error común es encender algo en una regla y no apagarlo nunca: pon el tiempo de vuelta o escribe la regla contraria.",
        "Fügen Sie eine oder mehrere Aktionen hinzu: ein Gerät ein- oder ausschalten oder die Alarmmeldung senden (MQTT und Webhook). Eine Aktion an einem Gerät kann sich mit \"danach zurück nach (Sekunden)\" selbst aufheben und das Gerät in den vorigen Zustand bringen; 0 lässt es, wie es ist. Ein häufiger Fehler: in einer Regel etwas einschalten und nie ausschalten - setzen Sie die Rückkehrzeit oder schreiben Sie die Gegenregel.",
        "Ajoutez une ou plusieurs actions : allumer ou éteindre un appareil, ou envoyer la notification d'alarme (MQTT et webhook). Une action sur un appareil peut s'annuler d'elle-même avec « puis retour après (secondes) », qui le remet dans son état précédent après ce délai ; 0 le laisse tel quel. Erreur courante : allumer quelque chose dans une règle sans jamais l'éteindre, réglez le délai de retour ou écrivez la règle inverse.",
        "Aggiungi una o più azioni: accendere o spegnere un dispositivo, o inviare la notifica di allarme (MQTT e webhook). Un'azione su un dispositivo può annullarsi da sola con \"poi torna dopo (secondi)\", che lo riporta allo stato precedente dopo quel tempo; 0 lo lascia com'è. Errore comune: accendere qualcosa in una regola e non spegnerlo mai: imposta il tempo di ritorno o scrivi la regola opposta.",
        "アクションを1つ以上追加します：デバイスのオン／オフ、またはアラーム通知（MQTTとWebhook）の送信。デバイスへのアクションは「その後、元に戻す（秒）」で自動的に元の状態へ戻せます（0なら戻さない）。よくある失敗は、ルールで点けたものを消すルールがないこと。戻し時間を設定するか、逆のルールを作りましょう。",
        "添加一个或多个动作：开关某个设备，或发送报警通知（MQTT 和 webhook）。对设备的动作可通过“然后在（秒）后恢复”自行撤销，到时间后设备回到之前的状态；0 表示保持不变。常见错误是规则里把东西打开却从不关掉：请设置恢复时间，或另写一条相反的规则。",
        "Adicione uma ou mais ações: ligar ou desligar um dispositivo, ou enviar a notificação de alarme (MQTT e webhook). Uma ação sobre um dispositivo pode desfazer-se sozinha com \"depois voltar após (segundos)\", que o devolve ao estado anterior passado esse tempo; 0 deixa-o como está. Um erro comum é ligar algo numa regra e nunca o desligar: defina o tempo de regresso ou escreva a regra contrária."] },
    { target: "auto-list", placement: "top",
      t: ["The list: enable, run now and the record", "La lista: activar, ejecutar ya y el registro", "Die Liste: aktivieren, jetzt ausführen, Protokoll", "La liste : activer, exécuter et le journal", "L'elenco: attiva, esegui ora e il registro", "一覧：有効化・今すぐ実行・記録", "列表：启用、立即运行与记录", "A lista: ativar, executar já e o registo"],
      b: ["Each automation reads as a sentence and shows when it last ran and how many times. Enable or disable it without deleting it; \"Run now\" runs it once whatever the condition, which is the safe way to try a rule, and the run is written in the audit trail (System). \"Save rules\" stores the list, so press it after changing anything. A rule that never runs is usually waiting for a device state that never comes: check the device in Devices.",
        "Cada automatización se lee como una frase y muestra cuándo se ejecutó por última vez y cuántas veces. Actívala o desactívala sin borrarla; \"Ejecutar ahora\" la ejecuta una vez sea cual sea la condición, que es la forma segura de probar una regla, y la ejecución queda en el registro de auditoría (Sistema). \"Guardar reglas\" guarda la lista, así que púlsalo tras cambiar algo. Una regla que nunca se ejecuta suele esperar un estado de dispositivo que no llega: revisa el dispositivo en Dispositivos.",
        "Jede Automation liest sich als Satz und zeigt, wann sie zuletzt lief und wie oft. Aktivieren oder deaktivieren Sie sie, ohne sie zu löschen; \"Jetzt ausführen\" führt sie einmal unabhängig von der Bedingung aus - der sichere Weg, eine Regel zu testen - und der Lauf steht im Audit-Protokoll (System). \"Regeln speichern\" sichert die Liste, drücken Sie es nach jeder Änderung. Eine Regel, die nie läuft, wartet meist auf einen Gerätezustand, der nicht kommt: Prüfen Sie das Gerät unter Geräte.",
        "Chaque automatisation se lit comme une phrase et montre quand elle a tourné pour la dernière fois et combien de fois. Activez-la ou désactivez-la sans la supprimer ; « Exécuter maintenant » l'exécute une fois quelle que soit la condition, la façon sûre d'essayer une règle, et l'exécution est écrite dans le journal d'audit (Système). « Enregistrer les règles » sauvegarde la liste, appuyez après chaque changement. Une règle qui ne tourne jamais attend souvent un état d'appareil qui ne vient pas : vérifiez l'appareil dans Appareils.",
        "Ogni automazione si legge come una frase e mostra quando è stata eseguita l'ultima volta e quante volte. Attivala o disattivala senza eliminarla; \"Esegui ora\" la esegue una volta qualunque sia la condizione, il modo sicuro per provare una regola, e l'esecuzione è scritta nel registro di audit (Sistema). \"Salva regole\" salva l'elenco, premilo dopo ogni modifica. Una regola che non gira mai di solito aspetta uno stato del dispositivo che non arriva: controlla il dispositivo in Dispositivi.",
        "各オートメーションは文章の形で読め、最終実行時刻と実行回数が出ます。削除せずに有効／無効を切り替えられ、「今すぐ実行」は条件に関係なく1回実行します。ルールを安全に試す方法で、実行は監査記録（システム）に残ります。「ルールを保存」で一覧が保存されるので、変更後は必ず押してください。一度も動かないルールは、デバイスが期待する状態にならないことが多いので、デバイスメニューで確認します。",
        "每条自动化都以一句话的形式呈现，并显示上次运行时间和运行次数。可以启用或停用而不必删除；“立即运行”不论条件如何都运行一次，是安全测试规则的方法，运行会记入审计记录（系统）。“保存规则”会保存列表，所以改动后请点击。一直不运行的规则通常是在等设备迟迟不出现的状态：请到“设备”检查该设备。",
        "Cada automatização lê-se como uma frase e mostra quando correu pela última vez e quantas vezes. Ative-a ou desative-a sem a apagar; \"Executar já\" executa-a uma vez seja qual for a condição, a forma segura de testar uma regra, e a execução fica no registo de auditoria (Sistema). \"Guardar regras\" guarda a lista, prima-o depois de alterar algo. Uma regra que nunca corre costuma esperar um estado de dispositivo que não chega: verifique o dispositivo em Dispositivos."] },
  ],
  network: [
    { target: "net-hero", placement: "bottom",
      t: ["Internet state, latency and outages", "Estado de internet, latencia y cortes", "Internetzustand, Latenz und Ausfälle", "État d'Internet, latence et coupures", "Stato di internet, latenza e interruzioni", "インターネット状態・遅延・停止", "互联网状态、延迟与中断", "Estado da internet, latência e quedas"],
      b: ["The big card says whether the internet is up, degraded or down (or only the local network is down) and since when. Next to it: latency, packet loss, the downtime of the last 24 hours (click it to read the outages of the day) and how many devices are online. These come from an ARMOR-NETWORK node, which only observes: nothing here changes any device. If the node itself is silent, a warning says so and the numbers are old.",
        "La tarjeta grande dice si internet está activo, degradado o caído (o solo la red local) y desde cuándo. A su lado: latencia, pérdida de paquetes, el tiempo caído en las últimas 24 horas (haz clic para leer los cortes del día) y cuántos dispositivos están en línea. Vienen de un nodo ARMOR-NETWORK, que solo observa: nada de aquí cambia ningún dispositivo. Si el propio nodo está en silencio, un aviso lo dice y las cifras son antiguas.",
        "Die große Karte sagt, ob das Internet läuft, gestört oder aus ist (oder nur das lokale Netz) und seit wann. Daneben: Latenz, Paketverlust, die Ausfallzeit der letzten 24 Stunden (anklicken, um die Ausfälle des Tages zu lesen) und wie viele Geräte online sind. Das kommt von einem ARMOR-NETWORK-Knoten, der nur beobachtet: nichts hier ändert ein Gerät. Schweigt der Knoten selbst, sagt es eine Warnung, und die Zahlen sind alt.",
        "La grande carte dit si Internet est actif, dégradé ou coupé (ou seulement le réseau local) et depuis quand. À côté : latence, perte de paquets, temps de coupure des dernières 24 heures (cliquez pour lire les coupures du jour) et nombre d'appareils en ligne. Cela vient d'un nœud ARMOR-NETWORK, qui ne fait qu'observer : rien ici ne modifie un appareil. Si le nœud lui-même est muet, un avertissement le dit et les chiffres sont anciens.",
        "La scheda grande dice se internet è attivo, degradato o fuori uso (o solo la rete locale) e da quando. Accanto: latenza, perdita di pacchetti, il tempo di fuori servizio delle ultime 24 ore (clicca per leggere le interruzioni del giorno) e quanti dispositivi sono online. Vengono da un nodo ARMOR-NETWORK, che si limita a osservare: nulla qui modifica un dispositivo. Se il nodo stesso è muto, un avviso lo dice e i numeri sono vecchi.",
        "大きなカードは、インターネットが正常・低下・停止（またはローカルのみ停止）のどれか、そしていつからかを示します。隣には遅延、パケット損失、直近24時間の停止時間（クリックで当日の停止を表示）、オンライン台数。これらはARMOR-NETWORKノードが観測した値で、ここから機器の設定が変わることはありません。ノード自身が無通信の場合は警告が出て、数値は古いものです。",
        "大卡片说明互联网是正常、降级还是中断（或仅局域网中断）以及从何时开始。旁边是延迟、丢包、最近 24 小时的中断时长（点击可查看当天的中断）以及在线设备数。这些数据来自 ARMOR-NETWORK 节点，它只观察：这里的任何操作都不会改动设备。如果节点本身沉默，会有警告提示，此时数字是旧的。",
        "O cartão grande diz se a internet está ativa, degradada ou em baixo (ou só a rede local) e desde quando. Ao lado: latência, perda de pacotes, o tempo em baixo nas últimas 24 horas (clique para ler as quedas do dia) e quantos dispositivos estão ligados. Vêm de um nó ARMOR-NETWORK, que só observa: nada aqui altera dispositivos. Se o próprio nó estiver em silêncio, um aviso di-lo e os números são antigos."] },
    { target: "net-public", placement: "bottom",
      t: ["Public connection", "Conexión pública", "Öffentliche Verbindung", "Connexion publique", "Connessione pubblica", "公開接続", "公网连接", "Ligação pública"],
      b: ["Right under the internet state, this card shows the address the Internet sees (your public IP, with a button to copy it), the provider and its network number (ASN), the place with its flag and country, the time there, IPv4 or IPv6, the reverse name, since when the address has not changed and when it was last checked. The node asks one public service now and then (one https request, nothing about the house) and can be told not to with --no-public-info.",
        "Justo bajo el estado de internet, esta tarjeta muestra la dirección que ve Internet (tu IP pública, con un botón para copiarla), el proveedor y su número de red (ASN), el lugar con su bandera y país, la hora allí, si es IPv4 o IPv6, el nombre inverso, desde cuándo no ha cambiado la dirección y cuándo se comprobó por última vez. El nodo consulta de vez en cuando un servicio público (una petición https, nada de la casa) y se le puede decir que no lo haga con --no-public-info.",
        "Direkt unter dem Internetzustand zeigt diese Karte die Adresse, die das Internet sieht (Ihre öffentliche IP, mit Kopierknopf), den Anbieter und seine Netznummer (ASN), den Ort mit Flagge und Land, die dortige Uhrzeit, IPv4 oder IPv6, den Reverse-Namen, seit wann sich die Adresse nicht geändert hat und wann zuletzt geprüft wurde. Der Knoten fragt ab und zu einen öffentlichen Dienst (eine https-Anfrage, nichts über das Haus) und lässt sich mit --no-public-info davon abhalten.",
        "Juste sous l'état d'Internet, cette carte montre l'adresse que voit Internet (votre IP publique, avec un bouton pour la copier), le fournisseur et son numéro de réseau (ASN), le lieu avec son drapeau et son pays, l'heure locale, IPv4 ou IPv6, le nom inverse, depuis quand l'adresse n'a pas changé et quand elle a été vérifiée. Le nœud interroge de temps en temps un service public (une requête https, rien sur la maison) et on peut le lui interdire avec --no-public-info.",
        "Subito sotto lo stato di internet, questa scheda mostra l'indirizzo che vede Internet (il tuo IP pubblico, con un pulsante per copiarlo), il provider e il suo numero di rete (ASN), il luogo con bandiera e paese, l'ora lì, IPv4 o IPv6, il nome inverso, da quando l'indirizzo non è cambiato e quando è stato controllato. Il nodo interroga ogni tanto un servizio pubblico (una richiesta https, nulla sulla casa) e si può dirgli di non farlo con --no-public-info.",
        "インターネット状態のすぐ下に、インターネットから見えるアドレス（グローバルIP、コピー用ボタン付き）、プロバイダーとそのネットワーク番号（ASN）、国旗付きの場所と国名、現地時間、IPv4／IPv6、逆引き名、アドレスが変わっていない期間、最終確認時刻が表示されます。ノードは時々公開サービスに1回問い合わせ（https 1回、家の情報は含まない）、--no-public-info で止められます。",
        "在互联网状态下方，此卡片显示互联网看到的地址（你的公网 IP，带复制按钮）、运营商及其网络号（ASN）、带国旗的地点和国家、当地时间、IPv4 或 IPv6、反向域名、地址多久没变以及上次检查时间。节点偶尔会询问一个公共服务（一次 https 请求，不含任何住宅信息），可用 --no-public-info 禁止。",
        "Logo por baixo do estado da internet, este cartão mostra o endereço que a Internet vê (o seu IP público, com um botão para o copiar), o fornecedor e o seu número de rede (ASN), o local com a bandeira e o país, a hora aí, IPv4 ou IPv6, o nome inverso, desde quando o endereço não mudou e quando foi verificado. O nó consulta de vez em quando um serviço público (um pedido https, nada da casa) e pode-se dizer-lhe que não o faça com --no-public-info."] },
    { target: "net-toolbar", placement: "bottom",
      t: ["Scan now, and the tabs", "Escanear ahora y las pestañas", "Jetzt scannen und die Reiter", "Scanner maintenant et les onglets", "Scansiona ora e le schede", "今すぐスキャンとタブ", "立即扫描与标签页", "Procurar agora e os separadores"],
      b: ["The line shows the node's interface, the network, the router, your public address and the last scan. \"Scan now\" asks the node to search the network at once; it answers when the scan ends. Under it, five tabs: Devices, Services (open ports found), Internet (probes and the outages), Traffic and Events (what changed). If the button is disabled, the node is silent or already scanning.",
        "La línea muestra la interfaz del nodo, la red, el router, tu dirección pública y el último escaneo. \"Escanear ahora\" pide al nodo buscar en la red de inmediato; responde cuando termina. Debajo, cinco pestañas: Dispositivos, Servicios (puertos abiertos hallados), Internet (sondas y cortes), Tráfico y Eventos (lo que cambió). Si el botón está desactivado, el nodo está en silencio o ya está escaneando.",
        "Die Zeile zeigt die Schnittstelle des Knotens, das Netz, den Router, Ihre öffentliche Adresse und den letzten Scan. \"Jetzt scannen\" bittet den Knoten, sofort das Netz zu durchsuchen; er antwortet nach dem Scan. Darunter fünf Reiter: Geräte, Dienste (gefundene offene Ports), Internet (Messungen und Ausfälle), Verkehr und Ereignisse (was sich änderte). Ist der Knopf deaktiviert, schweigt der Knoten oder scannt schon.",
        "La ligne montre l'interface du nœud, le réseau, le routeur, votre adresse publique et le dernier balayage. « Scanner maintenant » demande au nœud de parcourir le réseau tout de suite ; il répond à la fin. Dessous, cinq onglets : Appareils, Services (ports ouverts trouvés), Internet (sondes et coupures), Trafic et Événements (ce qui a changé). Si le bouton est désactivé, le nœud est muet ou déjà en train de scanner.",
        "La riga mostra l'interfaccia del nodo, la rete, il router, il tuo indirizzo pubblico e l'ultima scansione. \"Scansiona ora\" chiede al nodo di cercare subito nella rete; risponde al termine. Sotto, cinque schede: Dispositivi, Servizi (porte aperte trovate), Internet (sonde e interruzioni), Traffico ed Eventi (cosa è cambiato). Se il pulsante è disattivato, il nodo è muto o sta già scansionando.",
        "この行には、ノードのインターフェース、ネットワーク、ルーター、グローバルアドレス、最後のスキャンが出ます。「今すぐスキャン」でノードにすぐネットワークを調べさせ、終わると結果が返ります。その下に5つのタブ：デバイス、サービス（見つかった開放ポート）、インターネット（監視先と停止）、トラフィック、イベント（変化）。ボタンが無効なら、ノードが無通信かスキャン中です。",
        "这一行显示节点的接口、网络、路由器、你的公网地址和上次扫描。“立即扫描”请求节点马上搜索网络，完成后给出结果。下面有五个标签：设备、服务（发现的开放端口）、互联网（探测与中断）、流量和事件（发生的变化）。按钮不可用时，说明节点沉默或正在扫描。",
        "A linha mostra a interface do nó, a rede, o router, o seu endereço público e a última procura. \"Procurar agora\" pede ao nó que procure na rede de imediato; responde quando termina. Por baixo, cinco separadores: Dispositivos, Serviços (portas abertas encontradas), Internet (sondas e quedas), Tráfego e Eventos (o que mudou). Se o botão estiver desativado, o nó está em silêncio ou já está a procurar."] },
    { target: "net-filters", placement: "bottom",
      t: ["Filter the devices", "Filtrar los dispositivos", "Die Geräte filtern", "Filtrer les appareils", "Filtrare i dispositivi", "デバイスを絞り込む", "筛选设备", "Filtrar os dispositivos"],
      b: ["In the Devices tab, the search box looks by name, address, MAC or maker, the drop-down picks a kind (computer, phone, camera, printer...), and the buttons show only the ones not known or only the offline ones. The \"not known\" filter is the useful one: it lists what appeared on your network that nobody has welcomed yet, and each of them raised a new-device alarm.",
        "En la pestaña Dispositivos, el buscador busca por nombre, dirección, MAC o fabricante, el desplegable elige un tipo (ordenador, móvil, cámara, impresora...) y los botones muestran solo los no conocidos o solo los desconectados. El filtro \"no conocidos\" es el útil: lista lo que apareció en tu red sin que nadie lo haya aceptado, y cada uno levantó una alarma de dispositivo nuevo.",
        "Im Reiter Geräte sucht die Suche nach Name, Adresse, MAC oder Hersteller, das Auswahlmenü wählt eine Art (Computer, Handy, Kamera, Drucker...), und die Knöpfe zeigen nur die unbekannten oder nur die Offline-Geräte. Der Filter \"unbekannt\" ist der nützliche: Er listet, was in Ihrem Netz auftauchte, ohne dass es jemand willkommen geheißen hat, und jedes löste einen Neues-Gerät-Alarm aus.",
        "Dans l'onglet Appareils, la recherche cherche par nom, adresse, MAC ou fabricant, la liste choisit un type (ordinateur, téléphone, caméra, imprimante...) et les boutons n'affichent que les inconnus ou que les hors ligne. Le filtre « inconnus » est le plus utile : il liste ce qui est apparu sur votre réseau sans que personne l'ait accepté, et chacun a levé une alarme de nouvel appareil.",
        "Nella scheda Dispositivi, la ricerca cerca per nome, indirizzo, MAC o produttore, il menu sceglie un tipo (computer, telefono, telecamera, stampante...) e i pulsanti mostrano solo quelli non noti o solo gli offline. Il filtro \"non noti\" è quello utile: elenca ciò che è apparso nella tua rete senza che nessuno lo abbia accettato, e ognuno ha sollevato un allarme di nuovo dispositivo.",
        "デバイスタブでは、検索欄で名前・アドレス・MAC・メーカーを探し、ドロップダウンで種類（PC、スマホ、カメラ、プリンターなど）を選び、ボタンで「未確認のみ」「オフラインのみ」に絞れます。役に立つのは「未確認」で、ネットワークに現れたのにまだ誰も許可していない機器の一覧です。それぞれ新規デバイスのアラームを上げています。",
        "在“设备”标签页中，搜索框可按名称、地址、MAC 或厂商查找，下拉框选择类型（电脑、手机、摄像头、打印机等），按钮则只显示“未知”或只显示“离线”的设备。最有用的是“未知”筛选：它列出了出现在网络中却尚无人确认的设备，每一个都触发过新设备报警。",
        "No separador Dispositivos, a pesquisa procura por nome, endereço, MAC ou fabricante, a lista escolhe um tipo (computador, telemóvel, câmara, impressora...) e os botões mostram só os desconhecidos ou só os desligados. O filtro \"desconhecidos\" é o útil: lista o que apareceu na sua rede sem que ninguém o tenha aceite, e cada um levantou um alarme de dispositivo novo."] },
    { target: "net-table", placement: "top",
      t: ["A device and its tools", "Un dispositivo y sus herramientas", "Ein Gerät und seine Werkzeuge", "Un appareil et ses outils", "Un dispositivo e i suoi strumenti", "デバイスとそのツール", "设备及其工具", "Um dispositivo e as suas ferramentas"],
      b: ["Click a row to open the details: give the device a name of your own, a kind and notes, and mark it as known and welcome so it stops raising the new-device alarm; \"Forget what I noted\" removes your notes. The tools run from the network node: Ping and Traceroute, \"Look at the ports now\", \"Look at its web page\" (reads its title), \"Inspect its web login\" (it never tries passwords), Wake-on-LAN and \"Tell me when it connects again\". Nothing changes the device.",
        "Haz clic en una fila para abrir los detalles: da al dispositivo un nombre propio, un tipo y notas, y márcalo como conocido y bienvenido para que deje de levantar la alarma de dispositivo nuevo; \"Olvidar lo que anoté\" borra tus notas. Las herramientas se ejecutan desde el nodo de red: Ping y Traceroute, \"Mirar los puertos ahora\", \"Mirar su página web\" (lee su título), \"Inspeccionar su acceso web\" (nunca prueba contraseñas), Wake-on-LAN y \"Avísame cuando vuelva a conectarse\". Nada cambia el dispositivo.",
        "Klicken Sie eine Zeile an, um die Details zu öffnen: Geben Sie dem Gerät einen eigenen Namen, eine Art und Notizen und markieren Sie es als bekannt und willkommen, damit es den Neues-Gerät-Alarm nicht mehr auslöst; \"Meine Notizen vergessen\" löscht sie. Die Werkzeuge laufen vom Netzwerkknoten aus: Ping und Traceroute, \"Ports jetzt ansehen\", \"Webseite ansehen\" (liest den Titel), \"Web-Login prüfen\" (probiert nie Passwörter), Wake-on-LAN und \"Sag mir, wenn es sich wieder verbindet\". Nichts verändert das Gerät.",
        "Cliquez sur une ligne pour ouvrir les détails : donnez à l'appareil un nom à vous, un type et des notes, et marquez-le connu et bienvenu pour qu'il cesse de lever l'alarme de nouvel appareil ; « Oublier mes notes » les supprime. Les outils s'exécutent depuis le nœud réseau : Ping et Traceroute, « Regarder les ports maintenant », « Regarder sa page web » (lit son titre), « Inspecter son accès web » (n'essaie jamais de mots de passe), Wake-on-LAN et « Prévenez-moi quand il se reconnecte ». Rien ne modifie l'appareil.",
        "Clicca su una riga per aprire i dettagli: dai al dispositivo un nome tuo, un tipo e note, e segnalo come noto e benvenuto perché smetta di sollevare l'allarme di nuovo dispositivo; \"Dimentica ciò che ho annotato\" elimina le note. Gli strumenti girano dal nodo di rete: Ping e Traceroute, \"Guarda le porte ora\", \"Guarda la sua pagina web\" (legge il titolo), \"Ispeziona il suo accesso web\" (non prova mai password), Wake-on-LAN e \"Avvisami quando si ricollega\". Nulla modifica il dispositivo.",
        "行をクリックすると詳細が開きます。自分用の名前・種類・メモを付け、「既知・許可」にすると新規デバイスのアラームが止まります（「メモを忘れる」でメモ削除）。ツールはネットワークノードから実行されます：Ping／Traceroute、「今すぐポートを調べる」、「Webページを見る」（タイトル取得）、「Webログインを調べる」（パスワードは試しません）、Wake-on-LAN、「再接続したら知らせる」。機器の設定は一切変わりません。",
        "点击一行即可打开详情：为设备设置自己的名称、类型和备注，并标记为已知且受欢迎，它就不再触发新设备报警；“忘记我的备注”会删除备注。这些工具由网络节点运行：Ping 和路由追踪、“立即查看端口”、“查看其网页”（读取标题）、“检查其网页登录”（绝不尝试密码）、网络唤醒，以及“重新连接时通知我”。这些操作都不会改动设备。",
        "Clique numa linha para abrir os detalhes: dê ao dispositivo um nome seu, um tipo e notas, e marque-o como conhecido e bem-vindo para deixar de levantar o alarme de dispositivo novo; \"Esquecer o que anotei\" apaga as notas. As ferramentas correm a partir do nó de rede: Ping e Traceroute, \"Ver as portas agora\", \"Ver a sua página web\" (lê o título), \"Inspecionar o seu acesso web\" (nunca tenta palavras-passe), Wake-on-LAN e \"Avise-me quando voltar a ligar-se\". Nada altera o dispositivo."] },
  ],
};
